func TestCommentOnPullRequestsDeduplicatesAndPostsReleaseComment(t *testing.T) {
	t.Parallel()

	var commentPosts atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/api/v3/repos/owner/repo/commits/abc123/pulls", "/api/v3/repos/owner/repo/commits/def456/pulls":
			if r.Method != http.MethodGet {
				t.Fatalf("method = %s, want GET", r.Method)
			}
			_, _ = w.Write([]byte(`[{"number":7}]`))
		case "/api/v3/repos/owner/repo/issues/7/comments":
			switch r.Method {
			case http.MethodGet:
				_, _ = w.Write([]byte(`[]`))
			case http.MethodPost:
				var payload struct {
					Body string `json:"body"`
				}
				if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
					t.Fatalf("decode comment: %v", err)
				}
				if !strings.Contains(payload.Body, "<!-- semrel-release:v1.2.3 -->") ||
					!strings.Contains(payload.Body, "[v1.2.3](https://github.com/owner/repo/releases/tag/v1.2.3)") {
					t.Fatalf("unexpected comment body: %q", payload.Body)
				}
				commentPosts.Add(1)
				w.WriteHeader(http.StatusCreated)
			default:
				t.Fatalf("unexpected method %s", r.Method)
			}
		default:
			t.Fatalf("unexpected request: %s %s", r.Method, r.URL.Path)
		}
	}))
	defer server.Close()

	cli := New(server.Client()).(*client)
	err := cli.CommentOnPullRequests(context.Background(), Config{
		Token:        "token",
		Owner:        "owner",
		Repo:         "repo",
		BaseURL:      server.URL + "/api/v3",
		TagName:      "v1.2.3",
		CommentOnPRs: true,
		CommitHashes: []string{"abc123", "def456"},
	}, &Release{URL: "https://github.com/owner/repo/releases/tag/v1.2.3"})
	if err != nil {
		t.Fatalf("CommentOnPullRequests() error = %v", err)
	}
	if got := commentPosts.Load(); got != 1 {
		t.Fatalf("comment POST count = %d, want 1 for a PR associated with two commits", got)
	}
}

